-- Admin-run SELECT-only, rollback-only role simulation. Selects an existing UUID owner internally; no ID is returned.

-- This verifies policy semantics; root must also confirm real native authenticated sessions.

BEGIN READ ONLY;

DO $owner_probe$
DECLARE chosen text; baseline jsonb;
BEGIN
  SELECT s.user_id INTO chosen FROM public.chat_sessions s
    WHERE s.user_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND EXISTS (SELECT 1 FROM public.session_files f WHERE f.session_id=s.session_id)
    ORDER BY s.updated_at DESC NULLS LAST LIMIT 1;
  IF chosen IS NULL THEN RAISE EXCEPTION 'No existing UUID owner with files; root must choose a verified current authenticated owner'; END IF;
  PERFORM pg_catalog.set_config('pa.rls_probe_owner',chosen,true);
  PERFORM pg_catalog.set_config('request.jwt.claim.sub',chosen,true);
  PERFORM pg_catalog.set_config('request.jwt.claims',jsonb_build_object('sub',chosen,'role','authenticated')::text,true);
  SELECT jsonb_build_object('owned_counts',jsonb_build_object('chat_sessions', (SELECT count(*) FROM public.chat_sessions WHERE user_id=chosen),'chat_messages', (SELECT count(*) FROM public.chat_messages WHERE EXISTS (SELECT 1 FROM public.chat_sessions s WHERE s.session_id=chat_messages.session_id AND s.user_id=chosen)),'messages', (SELECT count(*) FROM public.messages WHERE EXISTS (SELECT 1 FROM public.chat_sessions s WHERE s.session_id=messages.session_id AND s.user_id=chosen)),'session_files', (SELECT count(*) FROM public.session_files WHERE EXISTS (SELECT 1 FROM public.chat_sessions s WHERE s.session_id=session_files.session_id AND s.user_id=chosen)),'workflow_steps', (SELECT count(*) FROM public.workflow_steps WHERE EXISTS (SELECT 1 FROM public.chat_sessions s WHERE s.session_id=workflow_steps.session_id AND s.user_id=chosen)),'shared_files', (SELECT count(*) FROM public.shared_files WHERE created_by=chosen)),'outside_counts',jsonb_build_object('chat_sessions', (SELECT count(*) FROM public.chat_sessions WHERE user_id IS DISTINCT FROM chosen),'chat_messages', (SELECT count(*) FROM public.chat_messages WHERE NOT EXISTS (SELECT 1 FROM public.chat_sessions s WHERE s.session_id=chat_messages.session_id AND s.user_id=chosen)),'messages', (SELECT count(*) FROM public.messages WHERE NOT EXISTS (SELECT 1 FROM public.chat_sessions s WHERE s.session_id=messages.session_id AND s.user_id=chosen)),'session_files', (SELECT count(*) FROM public.session_files WHERE NOT EXISTS (SELECT 1 FROM public.chat_sessions s WHERE s.session_id=session_files.session_id AND s.user_id=chosen)),'workflow_steps', (SELECT count(*) FROM public.workflow_steps WHERE NOT EXISTS (SELECT 1 FROM public.chat_sessions s WHERE s.session_id=workflow_steps.session_id AND s.user_id=chosen)),'shared_files', (SELECT count(*) FROM public.shared_files WHERE created_by IS DISTINCT FROM chosen))) INTO baseline;
  PERFORM pg_catalog.set_config('pa.rls_probe_baseline',baseline::text,true);
END
$owner_probe$;

SET LOCAL ROLE authenticated;

WITH checks AS (SELECT pg_catalog.current_setting('pa.rls_probe_baseline')::jsonb AS baseline, jsonb_build_object('chat_sessions', (SELECT count(*) FROM public.chat_sessions WHERE user_id=pg_catalog.current_setting('pa.rls_probe_owner')),'chat_messages', (SELECT count(*) FROM public.chat_messages WHERE EXISTS (SELECT 1 FROM public.chat_sessions s WHERE s.session_id=chat_messages.session_id AND s.user_id=pg_catalog.current_setting('pa.rls_probe_owner'))),'messages', (SELECT count(*) FROM public.messages WHERE EXISTS (SELECT 1 FROM public.chat_sessions s WHERE s.session_id=messages.session_id AND s.user_id=pg_catalog.current_setting('pa.rls_probe_owner'))),'session_files', (SELECT count(*) FROM public.session_files WHERE EXISTS (SELECT 1 FROM public.chat_sessions s WHERE s.session_id=session_files.session_id AND s.user_id=pg_catalog.current_setting('pa.rls_probe_owner'))),'workflow_steps', (SELECT count(*) FROM public.workflow_steps WHERE EXISTS (SELECT 1 FROM public.chat_sessions s WHERE s.session_id=workflow_steps.session_id AND s.user_id=pg_catalog.current_setting('pa.rls_probe_owner'))),'shared_files', (SELECT count(*) FROM public.shared_files WHERE created_by=pg_catalog.current_setting('pa.rls_probe_owner'))) AS owned, jsonb_build_object('chat_sessions', (SELECT count(*) FROM public.chat_sessions WHERE user_id IS DISTINCT FROM pg_catalog.current_setting('pa.rls_probe_owner')),'chat_messages', (SELECT count(*) FROM public.chat_messages WHERE NOT EXISTS (SELECT 1 FROM public.chat_sessions s WHERE s.session_id=chat_messages.session_id AND s.user_id=pg_catalog.current_setting('pa.rls_probe_owner'))),'messages', (SELECT count(*) FROM public.messages WHERE NOT EXISTS (SELECT 1 FROM public.chat_sessions s WHERE s.session_id=messages.session_id AND s.user_id=pg_catalog.current_setting('pa.rls_probe_owner'))),'session_files', (SELECT count(*) FROM public.session_files WHERE NOT EXISTS (SELECT 1 FROM public.chat_sessions s WHERE s.session_id=session_files.session_id AND s.user_id=pg_catalog.current_setting('pa.rls_probe_owner'))),'workflow_steps', (SELECT count(*) FROM public.workflow_steps WHERE NOT EXISTS (SELECT 1 FROM public.chat_sessions s WHERE s.session_id=workflow_steps.session_id AND s.user_id=pg_catalog.current_setting('pa.rls_probe_owner'))),'shared_files', (SELECT count(*) FROM public.shared_files WHERE created_by IS DISTINCT FROM pg_catalog.current_setting('pa.rls_probe_owner'))) AS outside) SELECT jsonb_build_object('current_user',current_user,'baseline_counts',baseline,'owned_visible_counts',owned,'outside_owner_visible_counts',outside,'owned_baseline_nonzero',(baseline->'owned_counts'->>'chat_sessions')::bigint>0 AND (baseline->'owned_counts'->>'session_files')::bigint>0,'outside_owner_baseline_nonzero',(baseline->'outside_counts'->>'chat_sessions')::bigint>0,'all_owned_counts_retained',owned = baseline->'owned_counts','all_outside_owner_counts_zero',NOT EXISTS (SELECT 1 FROM jsonb_each_text(outside) item WHERE item.value::bigint <> 0)) AS verification FROM checks;

ROLLBACK;
